// Official Michigan SOS sample-ballot data (public/data/ballots/<county>.json), generated by
// scripts/build-official-ballots.mjs. One file per county; each lists every city/township with
// all local races and proposals on the November 3, 2026 ballot.

const cache = new Map()

export function countySlug(name) {
  return String(name || '').replace(/\s+county$/i, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

export async function loadOfficialCounty(county) {
  if (!county) return null
  const slug = countySlug(county)
  if (!slug) return null
  if (!cache.has(slug)) {
    // Native app: pull from the live site so ballot data can update without an App Store release
    const base = (typeof window !== 'undefined' && window.Capacitor)
      ? 'https://www.offorandbythepeople.com/'
      : (import.meta.env?.BASE_URL || '/').replace(/\/?$/, '/')
    const p = fetch(`${base}data/ballots/${slug}.json`)
      .then(r => (r.ok ? r.json() : null))
      .catch(() => null)
    cache.set(slug, p)
  }
  return cache.get(slug)
}

export function normalizeJurisdiction(s) {
  return String(s || '').toLowerCase()
    .replace(/\b(charter|township|twp|city|village|of|the)\b/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ').trim()
}

export function matchJurisdiction(countyData, geo) {
  if (!countyData?.jurisdictions || !geo) return null
  const J = countyData.jurisdictions
  const place = normalizeJurisdiction(geo.place)
  const sub = normalizeJurisdiction(geo.countySubdivision)
  if (place) {
    const city = J.find(j => j.kind === 'city' && j.key === place)
    if (city) return city
  }
  if (sub) {
    const twp = J.find(j => j.kind === 'township' && j.key === sub) || J.find(j => j.key === sub)
    if (twp) return twp
  }
  if (place) {
    const any = J.find(j => j.key === place)
    if (any) return any
  }
  return null
}

const schoolTokens = s => normalizeJurisdiction(s).replace(/\b(public|schools?|community|area|district|consolidated)\b/g, ' ').split(/\s+/).filter(t => t.length >= 3)

// When a jurisdiction spans several school districts, keep only the school items for the user's district.
function filterBySchoolDistrict(items, geo, getDistrict) {
  const target = schoolTokens(geo?.schoolDistrict)
  if (!target.length) return items
  const schoolItems = items.filter(i => getDistrict(i))
  const districts = new Set(schoolItems.map(i => getDistrict(i)))
  if (districts.size <= 1) return items
  const matches = i => schoolTokens(getDistrict(i)).some(t => target.includes(t))
  if (!schoolItems.some(matches)) return items
  return items.filter(i => !getDistrict(i) || matches(i))
}

export function getOfficialBallot(countyData, geo) {
  const j = matchJurisdiction(countyData, geo)
  if (!j) return { matched: false, races: [], proposals: [] }
  const races = filterBySchoolDistrict(j.races, geo, r => (r.level === 'School Board' ? r.district : null))
  const proposals = filterBySchoolDistrict(j.proposals, geo, p => (p.division === 'Local School District' ? p.jurisdiction : null))
  return { matched: true, jurisdiction: j.name, precincts: j.precincts, ballotVariants: j.ballotVariants, races, proposals }
}
